pub(super) fn matches(program: &[u8], hash: blake3::Hash) -> bool {
    program.len() == 18_808_832 && *hash.as_bytes() == PROGRAM_HASH
}

pub(super) fn offset(original: usize, width: usize) -> usize {
    OFFSETS.binary_search_by_key(&(original, width), |&(at, len, _)| (at, len))
        .map_or(original, |index| OFFSETS[index].2)
}

// Check all the bytes that the pinned SDK will read before enabling it.
pub(super) fn verify(program: &[u8], map: &[u8]) -> bool {
    let mut hash = blake3::Hasher::new();
    for row in map[44..].chunks_exact(13) {
        let index = |start| u32::from_le_bytes(row[start..start + 4].try_into().unwrap()) as usize;
        let kind = row[0] & 0x7f;
        let width = match kind {
            0 => continue,
            1 | 2 => 4,
            3 => 8,
            4 | 5 => 2,
            _ => return false,
        };
        for source in [Some(index(1)), (kind == 5).then(|| index(5))].into_iter().flatten() {
            let at = offset(source, width);
            let Some(bytes) = program.get(at..at + width) else { return false };
            hash.update(bytes);
        }
    }
    *hash.finalize().as_bytes() == READS_HASH
}
